import hashlib
import hmac
import time
import sqlite3
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import threading

# Thread-safe rate limiter with lockout
class RateLimiter:
    def __init__(self, max_attempts=5, lockout_duration=300):
        self.max_attempts = max_attempts
        self.lockout_duration = lockout_duration
        self._lock = threading.Lock()
        # Store: {ip: {'count': int, 'first_attempt': float, 'locked_until': float}}
        self._attempts = {}

    def _cleanup_entry(self, ip):
        """Reset entry if window has expired."""
        entry = self._attempts.get(ip)
        if entry and time.time() - entry['first_attempt'] > 60:
            # Window expired, reset counter
            entry['count'] = 0
            entry['first_attempt'] = time.time()

    def is_locked(self, ip):
        """Check if IP is currently locked out."""
        with self._lock:
            entry = self._attempts.get(ip)
            if not entry:
                return False
            if entry.get('locked_until', 0) > time.time():
                return True
            # Lock expired, but DON'T reset count here
            return False

    def record_attempt(self, ip, success):
        """Record a login attempt. Returns True if account is now locked."""
        with self._lock:
            if ip not in self._attempts:
                self._attempts[ip] = {
                    'count': 0,
                    'first_attempt': time.time(),
                    'locked_until': 0
                }

            entry = self._attempts[ip]
            self._cleanup_entry(ip)

            if success:
                # Successful login: decrement counter as reward
                entry['count'] -= 1
                return False

            # Failed attempt: increment
            entry['count'] += 1

            # Check if we should lock - BUG: uses > instead of >=
            # This means at exactly max_attempts, no lock occurs
            # Combined with the decrement on success, counter can go negative
            # and then wrap behavior allows bypass
            if entry['count'] > self.max_attempts:
                entry['locked_until'] = time.time() + self.lockout_duration
                return True
            return False

    def get_remaining_attempts(self, ip):
        """Get remaining attempts before lockout."""
        with self._lock:
            entry = self._attempts.get(ip)
            if not entry:
                return self.max_attempts
            return self.max_attempts - entry['count']


class UserDatabase:
    def __init__(self, db_path=':memory:'):
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self._lock = threading.Lock()
        self._init_db()

    def _init_db(self):
        with self._lock:
            cursor = self.conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    password_hash TEXT NOT NULL,
                    role TEXT NOT NULL DEFAULT 'user',
                    is_active INTEGER NOT NULL DEFAULT 1,
                    failed_logins INTEGER NOT NULL DEFAULT 0
                )
            ''')
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS sessions (
                    token TEXT PRIMARY KEY,
                    user_id INTEGER NOT NULL,
                    created_at REAL NOT NULL,
                    expires_at REAL NOT NULL,
                    FOREIGN KEY (user_id) REFERENCES users(id)
                )
            ''')
            # Create default admin
            admin_hash = self._hash_password('admin_pass_2024')
            cursor.execute(
                'INSERT OR IGNORE INTO users (username, password_hash, role) VALUES (?, ?, ?)',
                ('admin', admin_hash, 'admin')
            )
            # Create test user
            user_hash = self._hash_password('user_pass')
            cursor.execute(
                'INSERT OR IGNORE INTO users (username, password_hash, role) VALUES (?, ?, ?)',
                ('testuser', user_hash, 'user')
            )
            self.conn.commit()

    def _hash_password(self, password):
        salt = os.urandom(16)
        dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return salt.hex() + ':' + dk.hex()

    def _verify_password(self, password, stored_hash):
        parts = stored_hash.split(':')
        if len(parts) != 2:
            return False
        salt = bytes.fromhex(parts[0])
        stored_dk = parts[1]
        dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(dk.hex(), stored_dk)

    def authenticate(self, username, password):
        """Authenticate user credentials. Returns user dict or None."""
        with self._lock:
            cursor = self.conn.cursor()
            cursor.execute(
                'SELECT id, username, password_hash, role, is_active FROM users WHERE username = ?',
                (username,)
            )
            row = cursor.fetchone()
            if not row:
                return None
            user_id, uname, pw_hash, role, is_active = row
            if not is_active:
                return None
            if self._verify_password(password, pw_hash):
                # Reset failed login counter
                cursor.execute(
                    'UPDATE users SET failed_logins = 0 WHERE id = ?',
                    (user_id,)
                )
                self.conn.commit()
                return {'id': user_id, 'username': uname, 'role': role}
            else:
                # Increment failed login counter in DB
                cursor.execute(
                    'UPDATE users SET failed_logins = failed_logins + 1 WHERE id = ?',
                    (user_id,)
                )
                self.conn.commit()
                return None

    def create_session(self, user_id):
        """Create a new session token."""
        token = os.urandom(32).hex()
        now = time.time()
        expires = now + 3600  # 1 hour
        with self._lock:
            cursor = self.conn.cursor()
            cursor.execute(
                'INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
                (token, user_id, now, expires)
            )
            self.conn.commit()
        return token

    def validate_session(self, token):
        """Validate session token. Returns user info or None."""
        with self._lock:
            cursor = self.conn.cursor()
            cursor.execute(
                '''SELECT s.user_id, u.username, u.role FROM sessions s
                   JOIN users u ON s.user_id = u.id
                   WHERE s.token = ? AND s.expires_at > ?''',
                (token, time.time())
            )
            row = cursor.fetchone()
            if row:
                return {'id': row[0], 'username': row[1], 'role': row[2]}
            return None

    def get_user_by_id(self, user_id):
        """Get user by ID."""
        with self._lock:
            cursor = self.conn.cursor()
            cursor.execute(
                'SELECT id, username, role, is_active FROM users WHERE id = ?',
                (int(user_id),)
            )
            row = cursor.fetchone()
            if row:
                return {'id': row[0], 'username': row[1], 'role': row[2], 'is_active': bool(row[3])}
            return None

    def deactivate_user(self, user_id):
        """Deactivate a user account. Admin only."""
        with self._lock:
            cursor = self.conn.cursor()
            cursor.execute(
                'UPDATE users SET is_active = 0 WHERE id = ?',
                (int(user_id),)
            )
            self.conn.commit()
            return cursor.rowcount > 0


# Global instances
rate_limiter = RateLimiter(max_attempts=5, lockout_duration=300)
db = UserDatabase()


class AuthHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path == '/api/login':
            self._handle_login()
        elif self.path == '/api/logout':
            self._handle_logout()
        else:
            self._send_json(404, {'error': 'Not found'})

    def do_GET(self):
        if self.path.startswith('/api/users/'):
            self._handle_get_user()
        elif self.path == '/api/me':
            self._handle_get_me()
        else:
            self._send_json(404, {'error': 'Not found'})

    def do_DELETE(self):
        if self.path.startswith('/api/users/'):
            self._handle_deactivate_user()
        else:
            self._send_json(404, {'error': 'Not found'})

    def _handle_login(self):
        client_ip = self.client_address[0]

        # Check rate limit
        if rate_limiter.is_locked(client_ip):
            self._send_json(429, {
                'error': 'Too many failed attempts. Account locked.',
                'retry_after': 300
            })
            return

        body = self._read_body()
        if not body:
            self._send_json(400, {'error': 'Invalid request body'})
            return

        username = body.get('username', '')
        password = body.get('password', '')

        if not username or not password:
            self._send_json(400, {'error': 'Username and password required'})
            return

        user = db.authenticate(username, password)

        if user:
            rate_limiter.record_attempt(client_ip, success=True)
            token = db.create_session(user['id'])
            self._send_json(200, {
                'token': token,
                'user': {'id': user['id'], 'username': user['username'], 'role': user['role']}
            })
        else:
            locked = rate_limiter.record_attempt(client_ip, success=False)
            remaining = rate_limiter.get_remaining_attempts(client_ip)
            if locked:
                self._send_json(429, {
                    'error': 'Account locked due to too many failed attempts',
                    'retry_after': 300
                })
            else:
                self._send_json(401, {
                    'error': 'Invalid credentials',
                    'remaining_attempts': remaining
                })

    def _handle_logout(self):
        # Simple logout - just return success
        self._send_json(200, {'message': 'Logged out'})

    def _handle_get_me(self):
        user = self._get_authenticated_user()
        if not user:
            return
        self._send_json(200, {'user': user})

    def _handle_get_user(self):
        user = self._get_authenticated_user()
        if not user:
            return
        # Extract user ID from path
        try:
            target_id = int(self.path.split('/')[-1])
        except (ValueError, IndexError):
            self._send_json(400, {'error': 'Invalid user ID'})
            return

        # Only admins can view other users
        if user['role'] != 'admin' and user['id'] != target_id:
            self._send_json(403, {'error': 'Forbidden'})
            return

        target = db.get_user_by_id(target_id)
        if target:
            self._send_json(200, {'user': target})
        else:
            self._send_json(404, {'error': 'User not found'})

    def _handle_deactivate_user(self):
        user = self._get_authenticated_user()
        if not user:
            return
        if user['role'] != 'admin':
            self._send_json(403, {'error': 'Admin access required'})
            return
        try:
            target_id = int(self.path.split('/')[-1])
        except (ValueError, IndexError):
            self._send_json(400, {'error': 'Invalid user ID'})
            return
        if db.deactivate_user(target_id):
            self._send_json(200, {'message': 'User deactivated'})
        else:
            self._send_json(404, {'error': 'User not found'})

    def _get_authenticated_user(self):
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self._send_json(401, {'error': 'Authentication required'})
            return None
        token = auth_header[7:]
        user = db.validate_session(token)
        if not user:
            self._send_json(401, {'error': 'Invalid or expired session'})
            return None
        return user

    def _read_body(self):
        try:
            length = int(self.headers.get('Content-Length', 0))
            if length > 10240:  # 10KB max
                return None
            raw = self.rfile.read(length)
            return json.loads(raw)
        except (json.JSONDecodeError, ValueError):
            return None

    def _send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())


if __name__ == '__main__':
    server = HTTPServer(('0.0.0.0', 8080), AuthHandler)
    print('Server running on port 8080')
    server.serve_forever()
